    if explanation:
        for w in ('Dc',)+(('Dr',) if observation['operation']!='profile' else ())+(('ROOTS',) if observation['parameters'].get('rootsTargets') else ()):
            t.wallet(w,caps(work=581671040,objects=270635588,scalar=50331776))
